True def transform(grid):
    out=[row[:] for row in grid]
    r=next(i for i,row in enumerate(grid) if any(v in (2,8) for v in row))
    for c,v in enumerate(grid[r]):
        if v in (2,8):
            height=min(4 if v==2 else 3,r)
            for k in range(1,height+1):
                out[r-k][c]=v if k==height else 1
    return out
